  "settings.whatsapp.retentionForeverWarning": "Con 0, este panel nunca borra nada de WhatsApp. El texto de las conversaciones, las fotos y los documentos que envió el abonado se guardan indefinidamente, y son el único dato del sistema sin plazo: la telemetría, los eventos del ERP, el aprovisionamiento y la pista de auditoría nacen todos con uno. Definir un plazo es lo que limita los datos personales que conservas y cuánto crece el disco.",
